package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.time.StopWatch#unsplit()
 */
public class StopWatch_unsplit_TriageGen0Test {

    @Test
    public void testUnsplit_WhenNotSplit_ThrowsIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        // Initial state is UNSPLIT. Calling unsplit should throw exception.
        try {
            stopWatch.unsplit();
            Assert.fail("Expected IllegalStateException to be thrown");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch has not been split. ", e.getMessage());
        }
    }

    @Test
    public void testUnsplit_WhenSplit_Success() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.split();

        // Verify it is in split state (indirectly via behavior or state if accessible)
        // Since we can't access private fields, we verify the successful execution 
        // and that it doesn't throw an exception.
        stopWatch.unsplit();

        // After unsplit, calling unsplit again should throw exception because state is now UNSPLIT
        try {
            stopWatch.unsplit();
            Assert.fail("Expected IllegalStateException to be thrown on second call");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch has not been split. ", e.getMessage());
        }
    }

    @Test
    public void testUnsplit_AfterStartStopSplit() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        // Simulate some time passing
        try { Thread.sleep(10); } catch (InterruptedException e) {}
        stopWatch.split();

        stopWatch.unsplit();

        // If unsplit worked, the internal stopTime should be reset (indicated by state change)
        // and we should be able to call split again without issue.
        stopWatch.split();
        // If it didn't fail, the state transition was correct.
    }

    @Test
    public void testUnsplit_WhenSuspendedAndSplit() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.suspend();
        stopWatch.split();

        // Should be able to unsplit even if suspended
        stopWatch.unsplit();

        try {
            stopWatch.unsplit();
            Assert.fail("Expected IllegalStateException");
        } catch (IllegalStateException e) {
            // Success
        }
    }
}
